from __future__ import annotations

from datetime import date

import polars as pl
from src.backtest.strategy import MarketView, Signal, Strategy


class RangeCompression(Strategy):
    rationale = (
        "Range compression indicates increased market volatility and can be a signal for "
        "potential breakout or continuation of the current trend. By identifying symbols where"
        " the range has significantly compressed, we aim to find opportunities."
    )

    def __init__(self, window: int = 20) -> None:
        self._window = window

    def generate(self, view: MarketView) -> Signal:
        stamp = _latest_visible(view)
        history = view.history(lookback=self._window)
        if history.height < (self._window * len(view.symbols)):
            return Signal(information_available_at=stamp, weights={})

        compressed_symbols = []
        for symbol in view.symbols:
            symbol_history = history.select(
                pl.col("symbol").eq(symbol).alias("is_symbol"),
                pl.col("high"),
                pl.col("low"),
            )
            if symbol_history["is_symbol"].sum() < self._window:
                continue

            high_min = symbol_history["high"].min().to_list()[0]
            low_max = symbol_history["low"].max().to_list()[0]
            range_compression = (high_min - low_max) / history.select(
                pl.col("symbol").eq(symbol)
            )[
                "adj_close"
            ].std().to_list()[
                0
            ]

            if range_compression < 0.1:
                compressed_symbols.append(symbol)

        if not compressed_symbols:
            return Signal(information_available_at=stamp, weights={})

        weight = 1.0 / len(compressed_symbols)
        return Signal(
            information_available_at=stamp,
            weights={s: weight for s in compressed_symbols},
        )


def _latest_visible(view: MarketView) -> date:
    visible = view.history()
    if visible.is_empty():
        return date(1900, 1, 1)
    newest = visible["session_date"].max().to_list()[0]
    assert isinstance(newest, date)
    return newest
